double absCenNormTrE2 = vCenNorm.x*vCenNorm.x + vCenNorm.y*vCenNorm.y; double absCenNormE2 = absCenNormTrE2 + vCenNorm.z*vCenNorm.z; if(absCenNormTrE2 < absCenNormE2*relTolZeroVectE2) TVector3d vDifOutIn = m_vOutLoc - m_vInLoc;
double absDifE2 = vDifOutIn.AmpE2();
 Special case: central normal parallel to the input (and output) optical axis if(absDifE2 < relTolZeroVectE2) { m_vHorOutIn.x = -1.; m_vHorOutIn.y = m_vHorOutIn.z = 0.; //= -vUx; m_vVerOutIn.y = 1.; m_vHorOutIn.x = m_vHorOutIn.z = 0.; //= vUy; }

General case: rotation about this axis: TVector3d vZero(0,0,0), vRotAxis(-vCenNorm.y, vCenNorm.x, 0.); //= vCenNorm^vUz
double rotAng = acos(m_vInLoc*m_vOutLoc);

gmTrans auxRot;
auxRot.SetupRotation(vZero, vRotAxis, rotAng);
m_vHorOutIn = auxRot.TrBiPoint(vUx); //output horizontal vector in the frame of input beam
m_vVerOutIn = auxRot.TrBiPoint(vUy); //output vertical vector in the frame of input beam
